// single-item input: one form submission is one request.
const f = $input.first().json || {};

const clean = (d) => String(d || '')
  .trim()
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/.*$/, '');

const you = clean(f['Your domain']);
const rivals = String(f['Competitor domains'] || '')
  .split(',')
  .map(clean)
  .filter(Boolean)
  .filter((d) => d !== you);

if (!you) throw new Error('Your domain is required.');
if (rivals.length < 2) {
  throw new Error('Give at least two competitor domains - an intersection of one is just their backlink profile.');
}
if (rivals.length > 5) {
  throw new Error('Five competitors is the ceiling. Every extra domain is another AND, and the intersection empties out fast.');
}

const tracker = String(f['Tracker sheet URL'] || '').trim();
if (!/^https:\/\/docs\.google\.com\/spreadsheets\//.test(tracker)) {
  throw new Error('The tracker needs to be a Google Sheets URL - the append node reads the document id out of it.');
}

const minRank = Math.min(Math.max(Number(f['Minimum domain rank']) || 200, 0), 1000);
const wanted = Math.min(Math.max(Number(f['How many prospects']) || 24, 6), 120);

// `targets` is an object keyed by position, and the filter and sort fields are
// addressed through those same keys - "1.rank", not "rank". Building it here
// keeps the numbering and the filter strings in one place.
const targets = {};
rivals.forEach((d, i) => { targets[String(i + 1)] = d; });

return [{
  json: {
    you,
    rivals,
    tracker,
    min_rank: minRank,
    wanted,
    body_gap: [{
      targets,
      // The gap. Anything that already links to you is not a prospect.
      exclude_targets: [you],
      filters: [
        ['1.rank', '>', minRank],
        'and',
        ['1.backlinks_spam_score', '<', 30],
      ],
      order_by: ['1.rank,desc'],
      // More than needed: the seen list and the traffic check both remove rows,
      // and a shortlist that has already been filtered twice is thin.
      limit: Math.min(wanted * 4, 500),
    }],
    body_pages: [{
      target: you,
      location_name: 'United States',
      language_name: 'English',
      limit: 10,
      order_by: ['metrics.organic.etv,desc'],
    }],
  },
}];

// single-item input: one intersection request per run.
const plan = $('Read The Form').first().json;
const body = $input.first().json || {};

// DataForSEO answers a bad filter path, an empty account and an unsupported
// order_by with HTTP 200 and a status code in the body. Reading result[0]
// without checking gives an undefined three nodes later, blaming the wrong one.
const task = (body.tasks || [])[0] || {};
if (Number(body.status_code) !== 20000 || Number(task.status_code) !== 20000) {
  throw new Error(
    'DataForSEO refused the intersection: ' +
    (task.status_code || body.status_code) + ' ' +
    String(task.status_message || body.status_message || '').slice(0, 200)
  );
}

const result = (task.result || [])[0] || {};
const items = result.items || [];

// Nobody pitches Google. These come back legitimately - google.com was in this
// intersection at rank 273 with 1.6 billion estimated visits, because it links
// to everybody - and a row you cannot email is a row that pushes a real one off
// the shortlist. The list is deliberately short and only holds platforms, not
// publishers.
const UNPITCHABLE = new Set([
  'google.com', 'youtube.com', 'facebook.com', 'instagram.com', 'x.com',
  'twitter.com', 'linkedin.com', 'pinterest.com', 'tiktok.com', 'reddit.com',
  'wikipedia.org', 'en.wikipedia.org', 'amazon.com', 'apple.com', 'microsoft.com',
]);

const prospects = [];
for (const it of items) {
  const per = it.domain_intersection || {};
  const keys = Object.keys(per);
  if (!keys.length) continue;
  const first = per[keys[0]] || {};
  const domain = String(first.target || '');
  if (!domain || UNPITCHABLE.has(domain)) continue;

  // Every key holds the same linking domain measured against a different
  // competitor. Rank belongs to the linking domain, so it is identical in each;
  // the link counts are not, and the earliest first_seen is the one that says
  // how long this site has been linking into your market.
  let backlinks = 0;
  let firstSeen = '';
  let spam = 0;
  for (const k of keys) {
    const v = per[k] || {};
    backlinks += Number(v.backlinks) || 0;
    spam = Math.max(spam, Number(v.backlinks_spam_score) || 0);
    const fs = String(v.first_seen || '').slice(0, 10);
    if (fs && (!firstSeen || fs < firstSeen)) firstSeen = fs;
  }

  prospects.push({
    domain,
    rank: Number(first.rank) || 0,
    spam_score: spam,
    links_to: keys.length,
    backlinks_to_rivals: backlinks,
    referring_domains: Number(first.referring_main_domains) || 0,
    first_seen: firstSeen,
  });
}

return [{
  json: {
    ...plan,
    total_found: Number(result.total_count) || 0,
    prospects,
  },
}];

// single-item input: one page request per run.
const body = $input.first().json || {};
const task = (body.tasks || [])[0] || {};

// A failed page lookup must not lose the prospect list. The angle is worse
// without it, so the failure is recorded and the run continues.
if (Number(body.status_code) !== 20000 || Number(task.status_code) !== 20000) {
  return [{
    json: {
      your_pages: [],
      pages_error: String(task.status_message || body.status_message || 'unknown error').slice(0, 160),
    },
  }];
}

const items = ((task.result || [])[0] || {}).items || [];
const pages = items.map((it) => ({
  url: String(it.page_address || ''),
  keywords: Number(((it.metrics || {}).organic || {}).count) || 0,
  traffic: Math.round(Number(((it.metrics || {}).organic || {}).etv) || 0),
})).filter((p) => p.url);

return [{ json: { your_pages: pages, pages_error: '' } }];

// single-item input: the Merge above is a barrier, and both branches are read
// back by name rather than off the appended stream.
const plan = $('Read The Prospects').first().json;
const pages = $('Read Your Best Pages').first().json || {};

const prospects = plan.prospects || [];

return [{
  json: {
    ...plan,
    your_pages: pages.your_pages || [],
    pages_error: pages.pages_error || '',
    prospect_count: prospects.length,
    // The traffic request is built here rather than upstream, because the
    // shortlist it measures is only settled once both branches have landed.
    // 200 targets is the documented ceiling for one bulk request.
    body_traffic: [{
      targets: prospects.slice(0, 200).map((p) => p.domain),
      location_name: 'United States',
      language_name: 'English',
    }],
  },
}];

// single-item input: one bulk traffic response covers the whole shortlist.
const plan = $('Put Both Halves Together').first().json;
const body = $input.first().json || {};

const traffic = new Map();
const task = (body.tasks || [])[0] || {};
if (Number(body.status_code) === 20000 && Number(task.status_code) === 20000) {
  for (const it of (((task.result || [])[0] || {}).items || [])) {
    const t = String(it.target || '').toLowerCase();
    const etv = Number(((it.metrics || {}).organic || {}).etv) || 0;
    if (t) traffic.set(t, Math.round(etv));
  }
}

// Rank is a backlink metric. A rank-300 domain nobody reads is still a domain
// nobody reads, so traffic is the second half of the score - logged, because a
// site with a hundred times the traffic is not a hundred times the link, and
// because some genuinely good resource pages carry very little search traffic
// and should sink rather than vanish.
const scored = (plan.prospects || []).map((p) => {
  const visits = traffic.get(p.domain) || 0;
  const reach = Math.log10(visits + 10);
  const clean = 1 - Math.min(p.spam_score, 30) / 60;
  return { ...p, monthly_visits: visits, score: Math.round(p.rank * reach * clean) };
}).sort((a, b) => b.score - a.score);

const shortlist = scored.slice(0, plan.wanted);

return [{
  json: {
    ...plan,
    shortlist,
    shortlist_count: shortlist.length,
    // The model is shown the head of the list only. Twenty-four prospects and
    // ten pages is already a long prompt, and the tail of a scored list is the
    // part nobody emails. Everything below the cut still ships, without an angle.
    for_model: shortlist.slice(0, 12).map((p) => ({
      domain: p.domain,
      rank: p.rank,
      monthly_visits: p.monthly_visits,
      links_to_rivals: p.links_to,
      first_seen: p.first_seen,
    })),
  },
}];

// single-item input: one model answer per run.
const plan = $('Score The Prospects').first().json;
const raw = String(($input.first().json || {}).text || '');

// The model was asked for bare JSON and returns a fenced block often enough to
// plan for. It also runs out of output tokens: measured on this template with
// twelve prospects, the array came back cut off inside the eighth object, and a
// strict parse threw away seven perfectly good angles with it. So the strict
// parse is tried first and a scan for complete objects is the fallback.
const scanObjects = (text) => {
  const found = [];
  let depth = 0, start = -1, inStr = false, esc = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') { if (depth === 0) start = i; depth += 1; }
    else if (c === '}') {
      depth -= 1;
      if (depth === 0 && start >= 0) {
        try { found.push(JSON.parse(text.slice(start, i + 1))); } catch (e) { /* half an object */ }
        start = -1;
      }
    }
  }
  return found;
};

const body = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let parsed = [];
let angleError = '';
try {
  const open = body.indexOf('[');
  const close = body.lastIndexOf(']');
  parsed = JSON.parse(open >= 0 ? body.slice(open, close + 1) : body);
  if (!Array.isArray(parsed)) parsed = [];
} catch (e) {
  parsed = [];
}
if (!parsed.length) {
  parsed = scanObjects(body);
  if (parsed.length) angleError = 'the answer was cut short, ' + parsed.length + ' angles recovered from it';
  else angleError = 'the angles could not be read at all';
}

const validPages = new Set((plan.your_pages || []).map((pg) => pg.url));
const byDomain = new Map();
for (const a of parsed) {
  const d = String((a || {}).domain || '').toLowerCase();
  if (!d) continue;
  // A pitch page that is not one of yours is a hallucination, and a row telling
  // somebody to pitch a URL that does not exist is worse than a blank one.
  const page = String(a.pitch_page || '');
  byDomain.set(d, {
    pitch_page: validPages.has(page) ? page : '',
    angle: String(a.angle || '').slice(0, 220),
  });
}

const today = new Date().toISOString().slice(0, 10);
const rows = (plan.shortlist || []).map((pr) => {
  const a = byDomain.get(pr.domain) || {};
  return {
    found_on: today,
    for_domain: plan.you,
    domain: pr.domain,
    score: pr.score,
    domain_rank: pr.rank,
    monthly_visits: pr.monthly_visits,
    spam_score: pr.spam_score,
    links_to_rivals: pr.links_to,
    first_linked: pr.first_seen,
    pitch_page: a.pitch_page || '',
    angle: a.angle || '',
    status: 'new',
  };
});

const notes = [];
if (angleError) notes.push(angleError);
if (plan.pages_error) notes.push('your pages could not be read: ' + plan.pages_error);

return [{ json: { rows, row_count: rows.length, notes, checked_on: today } }];

// single-item input: the shortlist arrives as one object.
// The Sheets append maps input fields to columns, so it needs one item per row.
// Handed the single object it would write one row whose columns are `rows`,
// `row_count` and `notes` - a JSON blob where the description promised a list.
const payload = $input.first().json || {};
return (payload.rows || []).map((json) => ({ json }));

// single-item input: one summary per run, built beside the sheet write rather
// than behind it.
const payload = $input.first().json || {};
const plan = $('Score The Prospects').first().json;
const rows = payload.rows || [];

const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const withAngle = rows.filter((r) => r.angle).length;
const summary =
  rows.length + ' link prospects for ' + plan.you + ' - domains linking to ' +
  plan.rivals.join(', ') + ' and not to you. ' + plan.total_found +
  ' matched the filters, ' + withAngle + ' came back with an angle.' +
  (payload.notes.length ? ' Note: ' + payload.notes.join('; ') + '.' : '');

const body = rows.slice(0, 40).map((r) => '<tr>' +
  '<td style="padding:6px;border-bottom:1px solid #eee">' + esc(r.domain) + '</td>' +
  '<td style="padding:6px;border-bottom:1px solid #eee;text-align:right">' + r.domain_rank + '</td>' +
  '<td style="padding:6px;border-bottom:1px solid #eee;text-align:right">' + r.monthly_visits.toLocaleString('en-US') + '</td>' +
  '<td style="padding:6px;border-bottom:1px solid #eee">' + esc(r.pitch_page) + '</td>' +
  '<td style="padding:6px;border-bottom:1px solid #eee">' + esc(r.angle) + '</td>' +
  '</tr>').join('');

const html =
  '<div style="font-family:-apple-system,Segoe UI,Arial,sans-serif;max-width:960px">' +
  '<h2>' + rows.length + ' link prospects for ' + esc(plan.you) + '</h2>' +
  '<p style="color:#555">Every one of these links to ' + esc(plan.rivals.join(', ')) +
  ' and to none of your pages. They have been appended to your tracker sheet.</p>' +
  (payload.notes.length ? '<p style="color:#a00">' + esc(payload.notes.join('; ')) + '</p>' : '') +
  '<table style="border-collapse:collapse;width:100%;font-size:14px">' +
  '<tr style="text-align:left;background:#f0f2f5">' +
  '<th style="padding:6px">Domain</th><th style="padding:6px">Rank</th>' +
  '<th style="padding:6px">Visits/mo</th><th style="padding:6px">Pitch</th>' +
  '<th style="padding:6px">Angle</th></tr>' + body + '</table></div>';

return [{ json: { html, summary, row_count: rows.length } }];
